-- ==========================================================================================
-- 03d_seed_text.sql  ·  Unstructured data for the AI layer: source-system catalogue, clinical
-- protocols (Cortex Search), clinical notes (AI_EXTRACT, AI_REDACT) and patient feedback (AI_SENTIMENT).
-- ==========================================================================================
USE ROLE LUZ_ADMIN;
USE WAREHOUSE LUZ_LOAD_WH;
USE DATABASE LUZSAUDE_DEMO;

-- ---------- Source-system catalogue (from the architecture page) ----------
INSERT OVERWRITE INTO REF.SOURCE_SYSTEMS
SELECT f.value:DOMAIN::STRING, f.value:SYSTEM_NAME::STRING, f.value:PRODUCT::STRING, f.value:DATA_DESCRIPTION::STRING, f.value:DAILY_VOLUME::STRING,
       f.value:INTEGRATION::STRING, f.value:FRESHNESS::STRING, f.value:RAW_TABLE::STRING
FROM TABLE(FLATTEN(INPUT => PARSE_JSON($$[{"DOMAIN": "Clínico", "SYSTEM_NAME": "Processo clínico eletrónico (HIS)", "PRODUCT": "ALERT® / Glintt HIS", "DATA_DESCRIPTION": "Episódios ADT, diagnósticos ICD-10, prescrições, sinais vitais, notas", "DAILY_VOLUME": "1,2 M eventos", "INTEGRATION": "HL7 v2 · motor de integração → Snowpipe Streaming", "FRESHNESS": "< 1 min", "RAW_TABLE": "RAW.HIS_ADT_HL7"}, {"DOMAIN": "Clínico", "SYSTEM_NAME": "Urgência e triagem de Manchester", "PRODUCT": "Módulo de urgência do HIS", "DATA_DESCRIPTION": "Episódios, prioridade, tempos por etapa", "DAILY_VOLUME": "84 mil eventos", "INTEGRATION": "HL7 v2 / FHIR R4 → Snowpipe Streaming", "FRESHNESS": "< 1 min", "RAW_TABLE": "RAW.HIS_ER_ENCOUNTER_FHIR"}, {"DOMAIN": "Clínico", "SYSTEM_NAME": "Bloco operatório e registo cirúrgico", "PRODUCT": "Módulo de bloco do HIS", "DATA_DESCRIPTION": "Planos, tempos de sala, equipas, checklist OMS", "DAILY_VOLUME": "22 mil eventos", "INTEGRATION": "HL7 SIU / FHIR Procedure → Snowpipe Streaming", "FRESHNESS": "< 1 min", "RAW_TABLE": "RAW.HIS_SURGERY_LOG"}, {"DOMAIN": "Clínico", "SYSTEM_NAME": "Laboratório (LIS)", "PRODUCT": "Clinidata®", "DATA_DESCRIPTION": "Pedidos e resultados codificados em LOINC", "DAILY_VOLUME": "310 mil resultados", "INTEGRATION": "HL7 ORU → Snowpipe Streaming", "FRESHNESS": "5 min", "RAW_TABLE": "RAW.LIS_RESULTS"}, {"DOMAIN": "Clínico", "SYSTEM_NAME": "Imagiologia (RIS e PACS)", "PRODUCT": "Agfa Enterprise Imaging", "DATA_DESCRIPTION": "Relatórios, metadados DICOM (as imagens ficam no PACS)", "DAILY_VOLUME": "210 mil registos", "INTEGRATION": "DICOM SR e ficheiros → Snowpipe", "FRESHNESS": "30 min", "RAW_TABLE": null}, {"DOMAIN": "Clínico", "SYSTEM_NAME": "Monitorização à cabeceira (UCI e bloco)", "PRODUCT": "Philips IntelliVue · Capsule", "DATA_DESCRIPTION": "Séries temporais de sinais vitais", "DAILY_VOLUME": "48 M leituras", "INTEGRATION": "Kafka → Snowpipe Streaming", "FRESHNESS": "segundos", "RAW_TABLE": null}, {"DOMAIN": "Clínico", "SYSTEM_NAME": "Farmácia hospitalar e dispensa automática", "PRODUCT": "Glintt · Omnicell", "DATA_DESCRIPTION": "Validação, dispensa, stock por armário", "DAILY_VOLUME": "96 mil movimentos", "INTEGRATION": "CDC · Openflow", "FRESHNESS": "15 min", "RAW_TABLE": null}, {"DOMAIN": "Clínico", "SYSTEM_NAME": "Esterilização e rastreio de kits", "PRODUCT": "Getinge T-DOC", "DATA_DESCRIPTION": "Ciclos, caixas, rastreabilidade por doente", "DAILY_VOLUME": "7 mil ciclos", "INTEGRATION": "API REST · Openflow", "FRESHNESS": "5 min", "RAW_TABLE": null}, {"DOMAIN": "Clínico", "SYSTEM_NAME": "Ensaios clínicos e investigação", "PRODUCT": "REDCap", "DATA_DESCRIPTION": "Formulários de estudo, recrutamento", "DAILY_VOLUME": "3 mil registos", "INTEGRATION": "API · Openflow", "FRESHNESS": "diária", "RAW_TABLE": null}, {"DOMAIN": "Financeiro", "SYSTEM_NAME": "Faturação clínica e convenções", "PRODUCT": "Módulo de faturação do HIS", "DATA_DESCRIPTION": "Atos, faturas, rejeições, notas de crédito", "DAILY_VOLUME": "3,4 M linhas", "INTEGRATION": "CDC · Openflow", "FRESHNESS": "15 min", "RAW_TABLE": "RAW.BILLING_INVOICES"}, {"DOMAIN": "Financeiro", "SYSTEM_NAME": "ERP · finanças, compras e stocks", "PRODUCT": "SAP S/4HANA", "DATA_DESCRIPTION": "FI/CO, MM, ativos, fornecedores", "DAILY_VOLUME": "960 mil linhas", "INTEGRATION": "Openflow · conector SAP", "FRESHNESS": "15 min", "RAW_TABLE": "RAW.SAP_STOCK_DAILY"}, {"DOMAIN": "Financeiro", "SYSTEM_NAME": "Seguradoras · autorizações e respostas", "PRODUCT": "Multicare, Médis, AdvanceCare", "DATA_DESCRIPTION": "Pedidos de autorização, respostas, motivos de rejeição", "DAILY_VOLUME": "41 mil mensagens", "INTEGRATION": "API e EDI · Openflow", "FRESHNESS": "horária", "RAW_TABLE": "RAW.PAYER_RESPONSES"}, {"DOMAIN": "Financeiro", "SYSTEM_NAME": "Subsistemas e SNS", "PRODUCT": "ADSE Direta · SPMS (RSE, CTH)", "DATA_DESCRIPTION": "Comparticipações, referenciação, convenções", "DAILY_VOLUME": "18 mil registos", "INTEGRATION": "SFTP e API → Snowpipe", "FRESHNESS": "diária", "RAW_TABLE": null}, {"DOMAIN": "Pessoas", "SYSTEM_NAME": "Recursos humanos e formação", "PRODUCT": "SAP SuccessFactors", "DATA_DESCRIPTION": "Colaboradores, carreiras, avaliação, formação", "DAILY_VOLUME": "14 mil perfis", "INTEGRATION": "OData · Openflow", "FRESHNESS": "diária", "RAW_TABLE": "RAW.SF_EMPLOYEES"}, {"DOMAIN": "Pessoas", "SYSTEM_NAME": "Escalas e assiduidade", "PRODUCT": "UKG Workforce Central", "DATA_DESCRIPTION": "Turnos, horas extra, ausências", "DAILY_VOLUME": "62 mil registos", "INTEGRATION": "API · Openflow", "FRESHNESS": "15 min", "RAW_TABLE": "RAW.UKG_SHIFTS"}, {"DOMAIN": "Cliente", "SYSTEM_NAME": "App e site MY LUZ", "PRODUCT": "Plataforma digital própria", "DATA_DESCRIPTION": "Sessões, marcações, check-in, pagamentos", "DAILY_VOLUME": "6,8 M eventos", "INTEGRATION": "Kafka → Snowpipe Streaming", "FRESHNESS": "< 1 min", "RAW_TABLE": "RAW.MYLUZ_EVENTS"}, {"DOMAIN": "Cliente", "SYSTEM_NAME": "CRM e campanhas", "PRODUCT": "Salesforce Health Cloud", "DATA_DESCRIPTION": "Contactos, campanhas, oportunidades corporativas", "DAILY_VOLUME": "240 mil registos", "INTEGRATION": "Openflow · conector Salesforce", "FRESHNESS": "15 min", "RAW_TABLE": null}, {"DOMAIN": "Cliente", "SYSTEM_NAME": "Centro de contacto", "PRODUCT": "Genesys Cloud CX", "DATA_DESCRIPTION": "Chamadas, chat, gravações (transcritas com IA)", "DAILY_VOLUME": "22 mil interações", "INTEGRATION": "API e ficheiros de áudio → stage", "FRESHNESS": "horária", "RAW_TABLE": null}, {"DOMAIN": "Cliente", "SYSTEM_NAME": "Inquéritos e reclamações", "PRODUCT": "Qualtrics · Livro de Reclamações", "DATA_DESCRIPTION": "NPS, comentários livres, reclamações", "DAILY_VOLUME": "9 mil respostas", "INTEGRATION": "API · Openflow", "FRESHNESS": "diária", "RAW_TABLE": "RAW.CUSTOMER_FEEDBACK"}, {"DOMAIN": "Documentos", "SYSTEM_NAME": "Documentos clínicos e administrativos", "PRODUCT": "Arquivo digital", "DATA_DESCRIPTION": "PDF de relatórios externos, consentimentos, faturas digitalizadas", "DAILY_VOLUME": "35 mil documentos", "INTEGRATION": "Stage interno · AI_PARSE_DOCUMENT", "FRESHNESS": "diária", "RAW_TABLE": "RAW.CLINICAL_NOTES"}, {"DOMAIN": "Externo", "SYSTEM_NAME": "Sinais externos", "PRODUCT": "IPMA, INSA, APA QualAr, INE, Google Trends", "DATA_DESCRIPTION": "Meteorologia, águas residuais, qualidade do ar, demografia, pesquisas", "DAILY_VOLUME": "13 fontes", "INTEGRATION": "Snowflake Marketplace · partilha sem cópias", "FRESHNESS": "diária", "RAW_TABLE": "EXT.*"}, {"DOMAIN": "Externo", "SYSTEM_NAME": "Parceiro · Fidelidade", "PRODUCT": "Data Clean Room", "DATA_DESCRIPTION": "Sinistralidade e utilização agregada (sem dados individuais)", "DAILY_VOLUME": "agregados", "INTEGRATION": "Snowflake Data Clean Rooms", "FRESHNESS": "diária", "RAW_TABLE": null}]$$))) f;

-- ---------- Clinical and administrative protocols ----------
INSERT OVERWRITE INTO REF.CLINICAL_PROTOCOLS
SELECT f.value[0]::STRING, f.value[1]::STRING, f.value[2]::STRING, f.value[3]::STRING, f.value[4]::STRING, f.value[5]::DATE, f.value[6]::STRING
FROM TABLE(FLATTEN(INPUT => PARSE_JSON($$[["PRT-001", "Protocolo de sépsis no adulto", "Protocolo clínico", "Medicina Interna", "Direção Clínica", "2026-03-12", "Reconhecimento precoce: suspeitar de sépsis perante infeção provável e qSOFA ≥ 2 (frequência respiratória ≥ 22/min, alteração do estado de consciência, pressão sistólica ≤ 100 mmHg). Na primeira hora: colher lactato e hemoculturas antes do antibiótico, iniciar antibioterapia empírica de largo espetro e fluidoterapia com 30 ml/kg de cristaloides se hipotensão ou lactato ≥ 4 mmol/L. Reavaliar o lactato em 2 a 4 horas. Ativar a equipa de emergência interna se não houver resposta. O alerta precoce de sépsis da Luz IA avisa a equipa quando os sinais vitais e as análises indicam risco elevado; a decisão é sempre do médico."], ["PRT-002", "Prevenção de quedas em internamento e residências", "Protocolo de enfermagem", "Enfermagem", "Direção de Enfermagem", "2026-02-02", "Avaliar o risco de queda à admissão e a cada 72 horas com a escala de Morse; nas residências usar também a escala de Tinetti. Risco elevado: cama baixa travada, campainha ao alcance, calçado antiderrapante, revisão da medicação sedativa e psicotrópica com o farmacêutico, rondas noturnas reforçadas e sensores de cama quando disponíveis. Após uma queda: avaliar lesão, registar no sistema de notificação de incidentes em 24 horas e rever o plano de cuidados."], ["PRT-003", "Altas antes das 12h", "Procedimento operacional", "Gestão de camas", "Direção de Operações", "2026-05-20", "Objetivo: libertar camas antes do pico de admissões da urgência da tarde. Na véspera, o médico assistente identifica as altas previstas e regista a data provável de alta; a enfermagem prepara medicação, ensinos e transporte. A previsão de altas da Luz IA indica os doentes com probabilidade de alta acima de 80% no dia seguinte. A gestão de camas confirma às 9h. Meta: 30% das altas até às 12h. Altas sociais: sinalizar ao serviço social com 48 horas de antecedência."], ["PRT-004", "Plano de contingência para picos de procura na urgência", "Plano de contingência", "Urgência", "Direção Clínica", "2026-10-15", "Ativado quando a previsão de afluência a 72 horas excede a capacidade em mais de 10% ou a ocupação prevista do internamento ultrapassa 92%. Nível 1: reforço de 2 médicos e 3 enfermeiros nas horas de pico, abertura da segunda sala de observação, triagem digital MY LUZ para casos não urgentes. Nível 2: antecipação de altas, transferências para o Hospital do Mar e cuidados continuados, adiamento de cirurgias programadas com internamento não urgente. A Direção Clínica aprova a ativação; o agente orquestrador prepara o plano e as notificações."], ["PRT-005", "Autorizações prévias de seguradoras", "Procedimento administrativo", "Faturação", "Direção Financeira", "2026-11-02", "Todos os atos com seguradora que constem da lista de atos sujeitos a autorização prévia devem ter pedido aprovado antes da realização, exceto urgências. Listas em vigor: Multicare (revista em 2026), Médis, AdvanceCare (nova lista de exames de imagiologia em vigor desde 01/11/2026, inclui ressonância magnética e tomografia computorizada programadas). O agente de autorizações prévias submete os pedidos por API e acompanha a resposta; pedidos recusados seguem para o gestor de processos. Sem autorização, o ato não deve ser faturado à seguradora."], ["PRT-006", "Codificação clínica e faturação de atos", "Procedimento administrativo", "Faturação", "Direção Financeira", "2025-12-01", "A codificação de diagnósticos usa a CID-10-CM e de procedimentos a CID-10-PCS. A codificação assistida pela Luz IA propõe códigos a partir da nota de alta; o codificador valida. Antes do envio, o modelo de risco de rejeição sinaliza faturas com probabilidade acima de 60% de devolução, indicando o motivo provável (autorização em falta, código incompatível, fora da cobertura, falta de justificação clínica, duplicação)."], ["PRT-007", "Preparação pré-operatória", "Protocolo clínico", "Bloco operatório", "Direção do Bloco", "2026-06-30", "Checklist obrigatória até 48 horas antes da cirurgia: consulta de anestesia, análises pré-operatórias (hemograma, coagulação, bioquímica), eletrocardiograma em doentes com mais de 50 anos ou cardiopatia, consentimento informado assinado, jejum e suspensão de anticoagulantes conforme indicação, reserva de cama de internamento e, se aplicável, de UCI. O agente de preparação pré-operatória contacta o doente pela app MY LUZ e sinaliza à equipa os itens em falta. Doentes com itens em falta na véspera têm risco elevado de cancelamento."], ["PRT-008", "Gestão do bloco operatório e tempos de sala", "Procedimento operacional", "Bloco operatório", "Direção do Bloco", "2026-04-14", "Primeira cirurgia com início às 8h00 na sala. Tempo-alvo de limpeza e preparação entre cirurgias: 22 minutos. A Sala 4 (Ortopedia, robô) é acompanhada semanalmente devido a tempos de preparação superiores. Caixas de instrumental robótico devem estar esterilizadas 60 minutos antes. A duração prevista pelo modelo (P50 e P90) é usada no plano operatório em vez da estimativa do cirurgião quando a diferença excede 20 minutos."], ["PRT-009", "Seguimento da diabetes tipo 2", "Norma clínica", "Endocrinologia", "Direção Clínica", "2025-11-20", "HbA1c a cada 3 a 6 meses; alvo individualizado, habitualmente inferior a 7%. Rastreio anual de retinopatia, exame do pé diabético e microalbuminúria anuais. Consulta de nutrição no diagnóstico e quando a HbA1c sobe em análises consecutivas. Reavaliar a terapêutica se a HbA1c subir em 3 análises seguidas ou se a adesão a um fármaco for inferior a 80%. As lacunas de cuidados são identificadas automaticamente no Doente 360°."], ["PRT-010", "Insuficiência cardíaca: alta e seguimento", "Norma clínica", "Cardiologia", "Direção Clínica", "2026-01-08", "Na alta: titulação de diuréticos, educação sobre sinais de alarme e pesagem diária. Contacto telefónico ou pela app em 72 horas e consulta em 7 a 14 dias. Aumento de peso superior a 2 kg em 3 dias exige contacto com a equipa. O modelo de readmissão a 30 dias prioriza os doentes com maior risco para seguimento ativo."], ["PRT-011", "Prevenção de infeções associadas aos cuidados de saúde", "Protocolo clínico", "Controlo de infeção", "Comissão de Controlo de Infeção", "2026-02-27", "Higiene das mãos nos 5 momentos, precauções de isolamento conforme o agente, feixes de intervenção para cateter venoso central, algaliação e pneumonia associada ao ventilador. Formação obrigatória anual em Prevenção de IACS para todos os enfermeiros; profissionais sem formação válida não podem ser escalados em quartos de isolamento."], ["PRT-012", "Proteção de dados de saúde e acesso ao processo", "Política", "Proteção de dados", "Encarregado de Proteção de Dados", "2026-01-15", "O acesso a dados clínicos é limitado a profissionais com relação terapêutica com o doente. Os perfis financeiros veem o episódio sem diagnóstico; as direções hospitalares veem apenas o seu hospital; os analistas trabalham com dados pseudonimizados. Os dados para investigação Learning Health só incluem doentes com consentimento e são pseudonimizados. Todos os acessos ficam registados e são auditados."], ["PRT-013", "Gestão de escalas e descanso", "Política de recursos humanos", "Recursos Humanos", "Direção de Recursos Humanos", "2026-03-03", "Descanso mínimo de 11 horas entre turnos. Limite recomendado de 12 horas extra por mês por profissional; acima de 20 horas durante 3 meses é sinalizado ao chefe de serviço. Pedidos de mudança de horário são respondidos em 15 dias. O modelo de risco de saída e de burnout apoia a decisão; nunca usa género, idade ou nacionalidade."], ["PRT-014", "Resposta a reclamações e elogios", "Procedimento", "Experiência do Cliente", "Direção de Experiência do Cliente", "2026-06-01", "Todas as reclamações têm resposta em 24 horas úteis e resolução em 10 dias úteis. As reclamações do Livro de Reclamações seguem o prazo legal. Os comentários dos inquéritos NPS são classificados por tema e sentimento com a Luz IA; temas com tendência negativa durante 2 semanas são apresentados à direção do hospital."], ["PRT-015", "Gestão de stocks e transferências entre hospitais", "Procedimento operacional", "Farmácia e logística", "Direção de Logística", "2026-07-10", "Stock de segurança definido por artigo e hospital com base na previsão de consumo. Quando a cobertura prevista é inferior a 7 dias, o agente de stocks procura excedentes noutros hospitais do grupo antes de propor compra. Artigos a menos de 60 dias do fim da validade são transferidos para hospitais com maior consumo."], ["PRT-016", "Triagem de Manchester e tempos-alvo", "Norma clínica", "Urgência", "Direção Clínica", "2025-12-10", "Tempos-alvo até à primeira observação médica: vermelho imediato, laranja 10 minutos, amarelo 60 minutos, verde 120 minutos, azul 240 minutos. Doentes verdes e azuis podem ser encaminhados para a via rápida ou para a teleconsulta LUZ 24. Retriar se a espera exceder o tempo-alvo."]]$$))) f;

-- ---------- Clinical notes: 3 412 documents from the last 30 days ----------
-- Templated progress notes, discharge letters and nursing notes; some carry signals the AI layer extracts
-- (sepsis criteria, fall risk, readmission risk, allergies, social discharge).
INSERT OVERWRITE INTO RAW.CLINICAL_NOTES
WITH a AS (
  SELECT MSG:PID:"3"::STRING pid, MSG:PV1:"3":"4"::STRING hosp, MSG:PV1:"19"::STRING ep, MSG:PV1:"10"::STRING spec, MSG:DG1:"3":"2"::STRING dx,
         TO_TIMESTAMP(MSG:PV1:"44"::STRING, 'YYYYMMDDHH24MISS') adm, ROW_NUMBER() OVER (ORDER BY MSG_ID) rn
  FROM RAW.HIS_ADT_HL7 WHERE MSG_TYPE = 'ADT^A01' AND RECEIVED_AT >= '2026-10-13'
), n AS (
  SELECT a.*, MOD(ABS(HASH(ep, 'type')), 3) t, MOD(ABS(HASH(ep, 'sig')), 9) sig, 50 + MOD(ABS(HASH(ep, 'age')), 45) age,
    ROUND(36.4 + 2.6 * REF.U(ep || 'temp'), 1) temp, 70 + MOD(ABS(HASH(ep, 'fc')), 55) hr, 85 + MOD(ABS(HASH(ep, 'pa')), 50) sbp,
    ROUND(0.9 + 4 * REF.U(ep || 'lac'), 1) lactate
  FROM a WHERE rn <= 3410
)
SELECT 'NT-' || ep, pid, hosp, ep,
  DECODE(t, 0, 'Nota de evolução', 1, 'Nota de alta', 'Nota de enfermagem'),
  DECODE(t, 2, 'Enfermeiro(a)', 'Médico(a)'),
  DATEADD(hour, 6 + MOD(ABS(HASH(ep, 'h')), 30), adm),
  DECODE(t,
    0, 'Doente de ' || age || ' anos internado em ' || spec || ' por ' || LOWER(dx) || '. ' ||
       DECODE(sig,
         0, 'Hoje febril (' || temp || ' °C), taquicárdico (' || hr || ' bpm) e com pressão sistólica de ' || sbp || ' mmHg. Lactato ' || lactate || ' mmol/L. Colhidas hemoculturas; iniciada antibioterapia empírica. Vigiar critérios de sépsis.',
         1, 'Desorientado durante a noite, levantou-se sozinho duas vezes. Sob benzodiazepina ao deitar. Pedida revisão da medicação e reforço de vigilância noturna por risco de queda.',
         2, 'Terceiro internamento por descompensação nos últimos 6 meses. Vive sozinho e não cumpre a pesagem diária. Necessita de seguimento ativo após a alta.',
         3, 'Alergia conhecida à penicilina (anafilaxia). Evolução favorável, apirético, sem queixas álgicas relevantes.',
         4, 'Clinicamente com critérios de alta, aguarda vaga em cuidados continuados. Sinalizado ao serviço social.',
         'Evolução favorável. Sinais vitais estáveis (FC ' || hr || ' bpm, PA sistólica ' || sbp || ' mmHg). Mantém plano terapêutico.'),
    1, 'Carta de alta. Diagnóstico principal: ' || dx || '. Internamento de ' || (1 + MOD(ABS(HASH(ep, 'los')), 9)) || ' dias em ' || spec || '. ' ||
       DECODE(sig,
         2, 'Alto risco de readmissão: idade ' || age || ', múltiplas comorbilidades, vive sozinho. Agendado contacto pela app MY LUZ em 72 horas e consulta em 7 dias.',
         3, 'Alergias: penicilina. Medicação de alta revista com o doente e a família.',
         4, 'Alta para unidade de cuidados continuados.',
         'Alta para o domicílio, com indicação para consulta de seguimento em 4 semanas. Sem alergias medicamentosas conhecidas.'),
    'Turno da noite: ' ||
       DECODE(sig,
         1, 'doente agitado, tentou levantar-se sem ajuda. Cama baixa e grades colocadas. Risco de queda elevado (Morse 65).',
         0, 'temperatura ' || temp || ' °C, frequência respiratória 24/min. Médico de serviço informado.',
         'sem intercorrências. Dormiu bem. Dor controlada (escala 2/10).'))
FROM n;

-- The featured patient's own notes, so her 360° view and the AI layer agree.
INSERT INTO RAW.CLINICAL_NOTES
SELECT 'NT-ANA-' || column1, 'PT0000001', 'H01', NULL, column2, 'Médico(a)', column3::TIMESTAMP_NTZ, column4 FROM VALUES
 ('1', 'Nota de consulta', '2026-10-02 10:20:00', 'Consulta de Medicina Geral. Diabetes tipo 2 desde 2019 e hipertensão. HbA1c subiu de 7,1% para 7,8% em três análises seguidas. Suspendeu a consulta de nutrição em outubro de 2025. Adesão à sitagliptina de 71% pelos levantamentos na farmácia. Atividade física em queda (−40% de passos na app). Rastreio de retinopatia em atraso há 9 meses. Alergia à penicilina (anafilaxia em 2011). Plano: marcar Endocrinologia e retomar Nutrição.'),
 ('2', 'Nota de teleconsulta', '2026-09-22 18:05:00', 'Teleconsulta LUZ 24. Queixa de cansaço e sede aumentada. Glicemias capilares em jejum entre 150 e 180 mg/dL. Reforçada a adesão terapêutica. Prefere consultas ao fim do dia e contacto pela app MY LUZ.');

-- ---------- Patient feedback: 9 000 NPS comments (last 90 days) ----------
INSERT OVERWRITE INTO RAW.CUSTOMER_FEEDBACK
WITH g AS (SELECT SEQ4() n FROM TABLE(GENERATOR(ROWCOUNT => 9000))),
c AS (
  SELECT n, MOD(ABS(HASH(n, 'tp')), 6) tp, MOD(ABS(HASH(n, 'tone')), 100) tone, MOD(ABS(HASH(n, 'v')), 3) v,
    'H' || LPAD(1 + MOD(ABS(HASH(n, 'h')), 15), 2, '0') hosp
  FROM g
)
SELECT 'FB-' || n, 'PT' || LPAD(1 + MOD(ABS(HASH(n, 'pt')), 400000), 7, '0'), hosp,
  DECODE(tp, 0, 'Urgência', 1, 'Consulta', 2, 'Internamento', 3, 'Faturação', 4, 'App MY LUZ', 'Marcação'),
  IFF(MOD(n, 7) = 0, 'Livro de Reclamações', 'Inquérito NPS'),
  IFF(tone < 77, 9 + MOD(n, 2), IFF(tone < 93, 7 + MOD(n, 2), MOD(n, 7))),
  DATEADD(minute, -FLOOR(REF.U(n || 't') * 129600), '2026-11-12 12:00:00'::TIMESTAMP_NTZ),
  CASE
    WHEN tone < 77 THEN DECODE(tp,
      0, DECODE(v, 0, 'Fui atendida rapidamente na urgência e a equipa de enfermagem foi muito atenciosa.', 1, 'Excelente atendimento na urgência pediátrica, o médico explicou tudo com calma.', 'Apesar de muita gente, a triagem foi rápida e fui bem tratado.'),
      1, DECODE(v, 0, 'A médica foi muito clara e dedicou o tempo necessário à consulta.', 1, 'Consulta a horas e o check-in pela app poupou-me imenso tempo.', 'Muito profissionais, saí da consulta com todas as dúvidas esclarecidas.'),
      2, DECODE(v, 0, 'O internamento correu muito bem, quartos limpos e enfermagem incansável.', 1, 'Agradeço a toda a equipa de Ortopedia pelo cuidado depois da cirurgia.', 'Comida boa, equipa simpática e alta bem explicada.'),
      3, DECODE(v, 0, 'A fatura chegou clara e o seguro tratou de tudo sem eu ter de fazer nada.', 1, 'Pagamento simples pela app.', 'Fui bem informada sobre o valor antes do exame.'),
      4, DECODE(v, 0, 'A app MY LUZ é muito prática para ver resultados e marcar consultas.', 1, 'Adoro poder fazer check-in no telemóvel.', 'A teleconsulta pela app funcionou na perfeição.'),
      DECODE(v, 0, 'Consegui marcar a consulta para a mesma semana.', 1, 'A Linha Luz foi rápida e simpática.', 'Marcação fácil pelo site.'))
    WHEN tone < 93 THEN DECODE(tp,
      0, 'O atendimento foi bom, mas a espera para ser visto pelo médico foi longa.',
      1, 'A consulta foi boa mas atrasou quase 40 minutos.',
      2, 'Equipa boa, mas o quarto era barulhento à noite.',
      3, 'O valor estava correto, mas demorei a perceber a fatura.',
      4, 'A app é útil, mas às vezes os resultados demoram a aparecer.',
      'Consegui marcar, mas só havia vagas daqui a dois meses.')
    ELSE DECODE(tp,
      0, DECODE(v, 0, 'Esperei mais de três horas na urgência com dores e ninguém me deu informação.', 1, 'A espera na urgência foi inaceitável, a sala estava cheia e sem cadeiras.', 'Triagem verde e fiquei quatro horas à espera. Muito mau.'),
      1, DECODE(v, 0, 'A consulta foi desmarcada no próprio dia sem aviso.', 1, 'O médico mal olhou para mim, consulta de cinco minutos.', 'Atraso de uma hora e meia na consulta.'),
      2, DECODE(v, 0, 'A alta demorou o dia inteiro e ninguém sabia dizer quando podia sair.', 1, 'A cirurgia foi adiada na véspera por falta de cama.', 'Pouca informação à família durante o internamento.'),
      3, DECODE(v, 0, 'Recebi uma fatura que não entendo, cobraram-me um exame que o seguro devia pagar.', 1, 'A seguradora recusou o exame por falta de autorização e ninguém me avisou antes.', 'Cobraram-me duas vezes o mesmo ato.'),
      4, DECODE(v, 0, 'A app está sempre a pedir para iniciar sessão.', 1, 'Não consigo ver os resultados das análises na app.', 'A teleconsulta caiu duas vezes.'),
      DECODE(v, 0, 'Liguei várias vezes para a Linha Luz e ninguém atendeu.', 1, 'Só havia vaga daqui a três meses para Dermatologia.', 'Marcaram a consulta para o hospital errado.'))
  END
FROM c;
